-- Read-only check: does the live database match the database files in the
-- CRM's code (supabase/schema.sql + supabase/migrations, up to 0193)?
-- It changes nothing. It lists only the differences:
--   only_live   : in the live database, no file in the code creates it
--   different   : both have it, but defined differently
--   missing_live: a file in the code creates it, the live database lacks it
-- Run it in Supabase -> SQL Editor, then Export -> Copy as JSON and paste the result to Claude.
set search_path to public, extensions;
with
objs as (
  select 'table:'||c.relname grp, 'table' kind, c.relname name,
         'kind='||c.relkind::text||' rls='||c.relrowsecurity||' force='||c.relforcerowsecurity
         ||' anon='||concat(case when has_table_privilege('anon',c.oid,'SELECT') then 's' end,case when has_table_privilege('anon',c.oid,'INSERT') then 'i' end,case when has_table_privilege('anon',c.oid,'UPDATE') then 'u' end,case when has_table_privilege('anon',c.oid,'DELETE') then 'd' end)
         ||' auth='||concat(case when has_table_privilege('authenticated',c.oid,'SELECT') then 's' end,case when has_table_privilege('authenticated',c.oid,'INSERT') then 'i' end,case when has_table_privilege('authenticated',c.oid,'UPDATE') then 'u' end,case when has_table_privilege('authenticated',c.oid,'DELETE') then 'd' end) def
  from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','p','v','m')
  union all
  select 'table:'||c.relname, 'column', a.attname,
         format_type(a.atttypid,a.atttypmod)||case when a.attnotnull then ' not null' else '' end
         ||coalesce(' default '||pg_get_expr(d.adbin,d.adrelid),'')||case when a.attgenerated::text<>'' then ' generated' else '' end
  from pg_attribute a join pg_class c on c.oid=a.attrelid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
  where c.relnamespace='public'::regnamespace and c.relkind in ('r','p') and a.attnum>0 and not a.attisdropped
  union all
  select 'table:'||c.relname, 'constraint', k.conname, pg_get_constraintdef(k.oid)
  from pg_constraint k join pg_class c on c.oid=k.conrelid where c.relnamespace='public'::regnamespace
  union all
  select 'table:'||c.relname, 'index', i.relname, pg_get_indexdef(i.oid)
  from pg_index x join pg_class i on i.oid=x.indexrelid join pg_class c on c.oid=x.indrelid where c.relnamespace='public'::regnamespace
  union all
  select 'table:'||c.relname, 'trigger', t.tgname, pg_get_triggerdef(t.oid)
  from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and not t.tgisinternal
  union all
  select case when p.schemaname='public' then 'table:' else p.schemaname||':' end||p.tablename, 'policy', p.policyname,
         p.cmd||' '||p.permissive||' '||p.roles::text||' using('||coalesce(p.qual,'')||') check('||coalesce(p.with_check,'')||')'
  from pg_policies p where p.schemaname in ('public','storage')
  union all
  select 'table:'||c.relname, 'view', c.relname, pg_get_viewdef(c.oid)
  from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('v','m')
  union all
  select 'function:'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')', 'function', p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',
         pg_get_functiondef(p.oid)
  from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind in ('f','p')
    and not exists (select 1 from pg_depend dp where dp.objid = p.oid and dp.deptype = 'e')
  union all
  select 'type:'||t.typname, 'enum', t.typname, (select string_agg(e.enumlabel, ',' order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)
  from pg_type t where t.typnamespace='public'::regnamespace and t.typtype='e'
    and not exists (select 1 from pg_depend dt where dt.objid = t.oid and dt.deptype = 'e')
  union all
  select 'bucket:'||b.id, 'bucket', b.id, 'public='||b.public from storage.buckets b
),
