live as (
  select grp, kind, name, def,
         left(md5(grp||'|'||kind||'|'||name), 8) k,
         left(md5(grp||'|'||kind||'|'||name||'|'||def), 8) h
  from objs
)
select 'info' status, 'version' kind, '' grp, '' name, version() def
union all
select case when e.k is null then 'only_live' else 'different' end, l.kind, l.grp, l.name, l.def
from live l left join expected e on e.k = l.k
where not exists (select 1 from expected x where x.k = l.k and x.h = l.h)
union all
select 'missing_live', '', '', e.k, ''
from expected e
where not exists (select 1 from live l where l.k = e.k)
order by 1, 3, 2, 4;
